{"content":"import React, { useState, useEffect } from "react";
import { Button } from "@/lib/ui";

export function OmniSearchWidget() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [history, setHistory] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem("lifeos_search_history") || "[]");
    } catch {
      return [];
    }
  });

  const saveHistory = (list) => {
    localStorage.setItem("lifeos_search_history", JSON.stringify(list));
    setHistory(list);
  };

  const handleSearch = async () => {
    if (!query.trim()) return;
    setLoading(true);

    // Simulate search results
    // In real integration, this would call the OmniSearchOS1 worker endpoint
    try {
      await new Promise(resolve => setTimeout(resolve, 800));
      const mockResults = [
        { id: Date.now(), label: `Search result for "${query}"`, type: "web" },
        { id: Date.now() + 1, label: `Related: "${query} guide"`, type: "doc" },
      ];
      setResults(mockResults);

      // Update history
      const newHistory = [query, ...history.filter(h => h !== query)].slice(0, 10);
      saveHistory(newHistory);
    } catch (error) {
      setResults([{ id: "error", label: "Search failed: " + error.message, type: "error" }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ fontSize: 8 }}>
      <div style={{ fontWeight: 700, marginBottom: 4, color: "var(--crimson)" }}>
        OmniSearch
      </div>
      <div style={{ display: "flex", gap: 4, marginBottom: 4 }}>
        <input
          value={query}
          onChange={e => setQuery(e.target.value)}
          onKeyDown={e => e.key === "Enter" && handleSearch()}
          placeholder="Search the web, docs, or create"
          style={{ flex: 1, fontSize: 8, padding: "2px 4px" }}
        />
        <Button onClick={handleSearch} disabled={loading} style={{ fontSize: 8, padding: "2px 6px" }}>
          {loading ? "…" : "Go"}
        </Button>
      </div>
      {results.length > 0 && (
        <div style={{ maxHeight: 60, overflow: "auto" }}>
          {results.map(r => (
            <div key={r.id} style={{ fontSize: 8, padding: "1px 0", color: r.type === "error" ? "#ff4f5e" : "var(--t2)" }}>
              {r.type === "error" ? "⚠ " : "🔍 "}{r.label}
            </div>
          ))}
        </div>
      )}
      {history.length > 0 && (
        <div style={{ marginTop: 4, fontSize: 7, color: "var(--t3)" }}>
          Recent: {history.slice(0, 3).join(", ")}
        </div>
      )}
    </div>
  );
}","path":"C:/dev/LifeOS1/src/components/lifeos/dashboard/OmniSearchWidget.jsx"}

{"content":"import React, { useState, useEffect } from "react";
import { Button } from "@/lib/ui";

export function VeritonOSWidget() {
  const [status, setStatus] = useState("idle");
  const [tasks, setTasks] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem("lifeos_veriton_tasks") || "[]");
    } catch {
      return [];
    }
  });
  const [newTask, setNewTask] = useState("");

  const saveTasks = (list) => {
    localStorage.setItem("lifeos_veriton_tasks", JSON.stringify(list));
    setTasks(list);
  };

  const addTask = () => {
    if (!newTask.trim()) return;
    const task = { id: Date.now(), label: newTask, done: false };
    saveTasks([...tasks, task]);
    setNewTask("");
  };

  const toggleTask = (id) => {
    saveTasks(tasks.map(t => t.id === id ? { ...t, done: !t.done } : t));
  };

  const runWorkflow = async () => {
    setStatus("running");
    // Simulate VeritonOS1 automation
    await new Promise(resolve => setTimeout(resolve, 1500));
    setStatus("completed");
    setTimeout(() => setStatus("idle"), 3000);
  };

  return (
    <div style={{ fontSize: 8 }}>
      <div style={{ fontWeight: 700, marginBottom: 4, color: "var(--crimson)" }}>
        VeritonOS Automation
      </div>
      <div style={{ marginBottom: 4 }}>
        <input
          value={newTask}
          onChange={e => setNewTask(e.target.value)}
          onKeyDown={e => e.key === "Enter" && addTask()}
          placeholder="Add automation task"
          style={{ width: "100%", fontSize: 8, padding: "2px 4px", marginBottom: 2 }}
        />
        <Button onClick={addTask} style={{ fontSize: 8, padding: "2px 6px", marginRight: 4 }}>
          Add Task
        </Button>
        <Button onClick={runWorkflow} disabled={status === "running"} style={{ fontSize: 8, padding: "2px 6px" }}>
          {status === "running" ? "Running..." : "Run Workflow"}
        </Button>
      </div>
      {status !== "idle" && (
        <div style={{ fontSize: 7, marginBottom: 4, color: status === "completed" ? "#00ff9d" : "var(--crimson)" }}>
          {status === "running" ? "⚙ Running automation..." : "✓ Workflow completed"}
        </div>
      )}
      {tasks.length > 0 && (
        <div style={{ maxHeight: 60, overflow: "auto" }}>
          {tasks.slice(-5).map(t => (
            <div key={t.id} style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 8, padding: "1px 0" }}>
              <input type="checkbox" checked={t.done} onChange={() => toggleTask(t.id)} />
              <span style={{ color: t.done ? "var(--t3)" : "var(--t2)", textDecoration: t.done ? "line-through" : "none" }}>
                {t.label}
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}","path":"C:/dev/LifeOS1/src/components/lifeos/dashboard/VeritonOSWidget.jsx"}

{"content":"import React, { useState, useEffect } from "react";
import { Button, Input } from "@/lib/ui";

export function CreatorOSWidget() {
  const [prompt, setPrompt] = useState("");
  const [type, setType] = useState<"image" | "video" | "audio" | "text">("image");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [spencerOnline, setSpencerOnline] = useState(true);
  const [spencerOllama, setSpencerOllama] = useState(true);
  const [spencerReply, setSpencerReply] = useState("");
  const [spencerErr, setSpencerErr] = useState("");
  const [spencerBusy, setSpencerBusy] = useState(false);

  const handleGenerate = async () => {
    setLoading(true);
    setSpencerBusy(true);
    setSpencerErr("");

    try {
      // Simulate CreatorOS1 API call
      await new Promise(resolve => setTimeout(resolve, 1200));

      // Generate a mock result based on type
      let mockResult;
      if (type === "image") {
        mockResult = "Generated image: " + prompt.substring(0, 20) + "...";
      } else if (type === "video") {
        mockResult = "Generated video: " + prompt.substring(0, 20) + "...";
      } else if (type === "audio") {
        mockResult = "Generated audio: " + prompt.substring(0, 20) + "...";
      } else {
        mockResult = "Generated text: " + prompt.substring(0, 20) + "...";
      }

      setResult(mockResult);

      // Simulate Ollama integration
      if (spencerOllama) {
        setSpencerReply(`[Ollama] ${mockResult}`);
      } else {
        setSpencerReply(`[Hermes] ${mockResult}`);
      }

    } catch (error) {
      setSpencerErr("Error: " + error.message);
    } finally {
      setLoading(false);
      setSpencerBusy(false);
    }
  };

  const askSpencer = async () => {
    if (!spencerOnline || !spencerOllama) return;

    setSpencerBusy(true);
    setSpencerErr("");

    try {
      // Simulate Spencer asking Ollama
      await new Promise(resolve => setTimeout(resolve, 1500));

      if (spencerOllama) {
        setSpencerReply("[Qwen3.6] " + prompt);
      } else {
        setSpencerReply("[Hermes API] " + prompt);
      }

    } catch (error) {
      setSpencerErr("Connection error: " + error.message);
    } finally {
      setSpencerBusy(false);
    }
  };

  return (
    <div style={{ fontSize: 8 }}>
      <div style={{ fontWeight: 700, marginBottom: 4, color: "var(--crimson)" }}>
        CreatorOS Quick Generate
      </div>

      <div style={{ display: "flex", gap: 4, marginBottom: 4 }}>
        <select value={type} onChange={e => setType(e.target.value as any)} style={{ fontSize: 8, padding: "2px 4px", minWidth: 80 }}>
          <option value="image">Image</option>
          <option value="video">Video</option>
          <option value="audio">Audio</option>
          <option value="text">Text</option>
        </select>
        <input
          value={prompt}
          onChange={e => setPrompt(e.target.value)}
          placeholder="Enter prompt for image/video/audio/text"
          style={{ flex: 1, fontSize: 8, padding: "2px 4px", minWidth: 80 }}
        />
        <Button 
          onClick={handleGenerate} 
          disabled={loading}
          style={{ fontSize: 8, padding: "2px 6px" }}
        >
          {loading ? "Working..." : "Generate"}
        </Button>
      </div>

      {result && (
        <div style={{ marginTop: 4, fontSize: 8, color: "var(--t2)" }}>
          {result}
        </div>
      )}

      <div style={{ marginTop: 4 }}>
        <div style={{ fontSize: 7, color: "var(--t3)", marginBottom: 4 }}>
          <strong>Spencer (Hermes) Status:</strong> 
          <span style={{ color: spencerOnline ? "#00ff9d" : "var(--t3)" }}>
            {spencerOnline ? "Online" : "Offline"}
          </span>
          &nbsp;|&nbsp;
          <span style={{ color: spencerOllama ? "#00ff9d" : "var(--t3)" }}>
            {spencerOllama ? "Qwen3.6 @ Ollama" : "Hermes API"}
          </span>
        </div>

        <div style={{ marginTop: 4 }}>
          <Button 
            onClick={askSpencer} 
            disabled={spencerBusy || !spencerOnline || !spencerOllama}
            style={{ fontSize: 8, padding: "2px 6px" }}
          >
            {spencerBusy ? "..." : "Ask Spencer"}
          </Button>

          <Input
            value={prompt}
            onChange={e => setPrompt(e.target.value)}
            placeholder="Ask about dashboard features..."
            style={{ fontSize: 8, padding: "2px 4px", marginLeft: 4, width: "150px" }}
          />
        </div>

        {spencerErr && (
          <div style={{ color: "#ff6b6b", fontSize: 8, marginTop: 4 }}>
            ⚠ {spencerErr}
          </div>
        )}

        <div style={{ marginTop: 4, fontSize: 7, color: "var(--t3)" }}>
          {spencerReply && <div style={{ marginTop: 2 }}>{spencerReply}</div>}
        </div>
      </div>
    </div>
  );
}","path":"C:/dev/LifeOS1/src/components/lifeos/dashboard/CreatorOSWidget.jsx"}

